/**
 * Writes research the API reads into TypeScript: research/<name>.json's
 * `<name>` list becomes src/lib/<name>.data.ts, exporting it as
 * `RESEARCH_<NAME>`. Vercel runs the API as compiled ES modules, which can't
 * import a JSON file without an import attribute, so research is never
 * imported as JSON; the app doesn't bundle the research's sources header
 * either. Run after the research changes:
 *
 *   npx tsx scripts/research.ts goals
 *
 * tests/research.test.ts fails while a generated file and its research disagree.
 */
import fs from 'node:fs';
import path from 'node:path';

const root = path.join(import.meta.dirname, '..');
export const researchFile = (name: string) => path.join(root, 'research', `${name}.json`);
export const dataFile = (name: string) => path.join(root, 'src', 'lib', `${name}.data.ts`);

/** The generated module for one research file: its `<name>` list (or the whole file when it has none). */
export function renderResearch(name: string): string {
  const json = JSON.parse(fs.readFileSync(researchFile(name), 'utf8'));
  const list = json && typeof json === 'object' && name in json ? json[name] : json;
  const id = `RESEARCH_${name.replace(/[^a-z0-9]+/gi, '_').toUpperCase()}`;
  return `/** Generated by scripts/research.ts from research/${name}.json. Don't edit: change the research and run it again. */\nexport const ${id}: unknown = ${JSON.stringify(list, null, 2)};\n`;
}

/** Every research file that has a generated twin. */
export const generated = () => (fs.existsSync(path.join(root, 'research')) ? fs.readdirSync(path.join(root, 'research')).filter((f) => f.endsWith('.json')).map((f) => f.replace(/\.json$/, '')).filter((n) => fs.existsSync(dataFile(n))) : []);

if (process.argv[1] && path.resolve(process.argv[1]) === path.resolve(import.meta.filename)) {
  const names = process.argv.slice(2);
  if (!names.length) throw new Error('Which research? npx tsx scripts/research.ts <name> (research/<name>.json)');
  for (const name of names) {
    fs.writeFileSync(dataFile(name), renderResearch(name));
    console.log(`wrote src/lib/${name}.data.ts`);
  }
}
